const emailBody = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const teamMembers = $('Load Team List').all().map(r => r.json).filter(r => r.email && r.name);
const surveyDate = new Date().toISOString().split('T')[0];
return [{ json: { emailBody, teamMembers, surveyDate, surveyId: `PS-${Date.now()}` } }];

const body = $input.first().json.body;
const required = ['respondent_name', 'energy_score'];
const missing = required.filter(f => body[f] === undefined || body[f] === null);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const energy = parseInt(body.energy_score);
if (isNaN(energy) || energy < 1 || energy > 5) return [{ json: { valid: false, error: 'energy_score must be 1-5' } }];
return [{ json: {
  valid: true,
  surveyId: body.survey_id || '',
  respondentName: body.respondent_name.trim(),
  respondentEmail: body.respondent_email || '',
  energyScore: energy,
  openResponse1: (body.open_response_1 || '').slice(0, 600),
  openResponse2: (body.open_response_2 || '').slice(0, 600),
  additionalScore: body.additional_score ? parseInt(body.additional_score) : null,
  submittedAt: new Date().toISOString()
} }];

const all = $input.all().map(r => r.json).filter(r => r.submitted_at);
const current = $('Validate Response').first().json;
const currentSurveyId = current.surveyId;
const thisSurvey = all.filter(r => !currentSurveyId || r.survey_id === currentSurveyId);
const last4Surveys = {};
for (const r of all) {
  if (!last4Surveys[r.survey_id]) last4Surveys[r.survey_id] = [];
  last4Surveys[r.survey_id].push(parseFloat(r.energy_score)||0);
}
const surveyAvgs = Object.entries(last4Surveys)
  .map(([id, scores]) => ({ id, avg: scores.reduce((a,b)=>a+b,0)/scores.length }))
  .sort((a,b) => b.id.localeCompare(a.id))
  .slice(0,4);
const thisAvg = thisSurvey.length ? (thisSurvey.reduce((s,r)=>s+(parseFloat(r.energy_score)||0),0)/thisSurvey.length).toFixed(1) : null;
const openResponses = thisSurvey.map(r => [r.open_response_1, r.open_response_2].filter(Boolean)).flat().filter(Boolean);
return [{ json: { thisAvg, responseCount: thisSurvey.length, surveyAvgs, openResponses, lowEnergyCount: thisSurvey.filter(r=>parseFloat(r.energy_score)<=2).length } }];

